schema:
CREATE TABLE agent (
  id INT PRIMARY KEY,
  name VARCHAR(50)
);
CREATE TABLE client (
  id INT PRIMARY KEY,
  name VARCHAR(50),
  phone VARCHAR(50)
);
CREATE TABLE property (
  id INT PRIMARY KEY,
  agent_id INT REFERENCES agent(id),
  address VARCHAR(50),
  property_type VARCHAR(20),
  price DECIMAL(12,2)
);
CREATE TABLE listing (
  id INT PRIMARY KEY,
  property_id INT REFERENCES property(id),
  client_id INT REFERENCES client(id),
  listed_date DATE,
  status VARCHAR(20)
);

